// Trigger & Sampler — "Run Once for All Items"
// Input : one item from Extract From File → { data: [session, session, ...] }
// Output: one n8n item per session, carrying a bounded sample (first 40 + last 20 turns)
const HEAD_TURNS = 40;
const TAIL_TURNS = 20;

const sessions = $input.all().flatMap(({ json }) =>
  Array.isArray(json.data) ? json.data : [json.data ?? json]
);

return sessions.map((session) => {
  const turns = Array.isArray(session.transcript) ? session.transcript : [];
  const truncated = turns.length > HEAD_TURNS + TAIL_TURNS;

  // Short transcripts are taken whole so no turn is ever duplicated by overlapping slices
  const sample = truncated
    ? [...turns.slice(0, HEAD_TURNS), ...turns.slice(-TAIL_TURNS)]
    : turns;

  return {
    json: {
      session_id: session.id,
      title: session.title ?? null,
      created_at: session.created_at ?? null,
      participants: session.participants ?? [],
      total_turns: turns.length,
      sampled_turns: sample.length,
      truncated,
      sample,
      session, // full raw session, needed later by the Dual-Stream Parser
    },
  };
});

// Build Classifier Request — "Run Once for Each Item"
// Turns the bounded sample into an Ollama /api/chat request body.
const MODEL = 'qwen3:4b-instruct';

const roster = $json.participants
  .map((p) => `- ${p.name} (${p.is_team_member ? 'internal team member' : 'external participant'})`)
  .join('\n');

const dialogue = $json.sample
  .map((t) => `[${t.timestamp}] ${t.speaker}: ${t.text}`)
  .join('\n');

const systemPrompt = `You are the ingestion gate for an executive-coaching firm's knowledge base.
Read the meeting sample and classify the meeting into exactly one category:

- Client Coaching: a coach working with an external client on leadership, wellbeing, behaviour, delegation or professional growth.
- Internal Operations: internal team members working on the business itself, such as engineering, tooling, CRM, integrations, sprints or processes.
- Sales Discovery: a sales conversation with a prospect about needs, pricing, budget, packages or contracts.
- Other: a meeting that fits none of the categories above.

Respond with a single JSON object with exactly these keys:
{"meeting_type": "Client Coaching" | "Internal Operations" | "Sales Discovery" | "Other",
 "confidence_score": a number from 0.0 to 1.0 expressing how clearly the meeting matches the chosen category,
 "summary": "one or two sentences describing what the meeting was about"}`;

const userPrompt = `Meeting title: ${$json.title}
Participants:
${roster}

Transcript sample (${$json.sampled_turns} of ${$json.total_turns} turns):
${dialogue}`;

return {
  json: {
    ...$json,
    llm_request: {
      model: MODEL,
      stream: false,
      format: 'json',
      options: { temperature: 0, num_ctx: 8192 },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt },
      ],
    },
  },
};

// Safe Parse Classification — "Run Once for Each Item"
// Never throws. Any malformed / missing / out-of-range output collapses to
// { meeting_type: "Other", confidence_score: 0 }, which the gate rejects (fail-closed).
const ALLOWED_TYPES = ['Client Coaching', 'Internal Operations', 'Sales Discovery', 'Other'];
const FALLBACK = { meeting_type: 'Other', confidence_score: 0, summary: '' };

const source = $('Build Classifier Request').item.json;
const raw = $json.message?.content ?? '';

function tryParse(text) {
  try {
    return JSON.parse(text);
  } catch {
    // Recover a JSON object wrapped in prose or code fences
    const match = String(text).match(/\{[\s\S]*\}/);
    if (!match) return null;
    try {
      return JSON.parse(match[0]);
    } catch {
      return null;
    }
  }
}

const parsed = tryParse(raw);
let result = { ...FALLBACK };
let parse_status = 'ok';

if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  parse_status = 'invalid_json';
} else {
  const type = ALLOWED_TYPES.find(
    (t) => t.toLowerCase() === String(parsed.meeting_type ?? '').trim().toLowerCase()
  );
  const score = Number(parsed.confidence_score);

  if (!type) {
    parse_status = 'unknown_meeting_type';
  } else if (!Number.isFinite(score) || score < 0 || score > 1) {
    // Out-of-range scores (e.g. 7, 85) are ambiguous, so they fail closed instead of being clamped
    parse_status = 'invalid_confidence';
  } else {
    result = {
      meeting_type: type,
      confidence_score: score,
      summary: typeof parsed.summary === 'string' ? parsed.summary.trim() : '',
    };
  }
}

// Deterministic consistency check: a coaching session needs an external client.
// If every participant is an internal team member, the LLM's "Client Coaching"
// label is overridden, because self-reported LLM confidence is not calibrated.
const hasExternalClient = (source.participants ?? []).some((p) => p.is_team_member === false);
if (result.meeting_type === 'Client Coaching' && !hasExternalClient) {
  result = { ...result, meeting_type: 'Internal Operations', confidence_score: 0 };
  parse_status = 'overridden_no_external_client';
}

const { llm_request, ...session } = source;

return {
  json: {
    ...session,
    ...result,
    parse_status,
    raw_llm_output: parse_status === 'ok' ? undefined : raw,
  },
};

// Build Framework Request — "Run Once for Each Item"
// Approved sessions only. Asks the LLM for (a) a dense conceptual takeaway of the
// coaching framework (Stream 1) and (b) a retrieval context — the client's situation
// and the questions a leader would ask — used only to enrich the embedding text.
// Stream 2 (voice samples) is extracted deterministically, without the LLM.
const MODEL = 'qwen3:4b-instruct';

const dialogue = $json.session.transcript
  .map((t) => `[${t.timestamp}] ${t.speaker}: ${t.text}`)
  .join('\n');

const systemPrompt = `You distill coaching sessions into reusable knowledge-base entries.

1. Identify the coaching framework the coach teaches and write a dense conceptual takeaway:
   the framework's name, the core principle behind it, the diagnostic or decision logic it uses,
   and how the client applies it. Keep the coach's own terminology. 80-150 words, third person.
2. Describe the client's situation in 1-2 general sentences (roles, not names), as a leader would describe their own problem.
3. Write 4 short questions a leader in that situation would ask a coach, in the leader's own words.

Respond with a single JSON object:
{"framework_name": "name of the framework as the coach calls it",
 "takeaway": "the dense conceptual takeaway",
 "situation": "the client's situation in general terms",
 "client_questions": ["question 1", "question 2", "question 3", "question 4"]}`;

const userPrompt = `Session: ${$json.title} (${$json.session_id})
Transcript:
${dialogue}`;

return {
  json: {
    ...$json,
    llm_request: {
      model: MODEL,
      stream: false,
      format: 'json',
      options: { temperature: 0, num_ctx: 8192 },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt },
      ],
    },
  },
};

// Dual-Stream Parser — "Run Once for Each Item"
// Splits one approved session into two arrays:
//   framework    : the LLM's dense conceptual takeaway (safely parsed)
//   voice_sample : the coach's verbatim turns, packed into 400–700 char chunks
const MIN_CHARS = 400;
const MAX_CHARS = 700;

const src = $('Build Framework Request').item.json;
const { session } = src;

// ---------- Stream 1: framework ----------
function parseFramework(raw) {
  const text = String(raw ?? '');
  const candidates = [text, text.match(/\{[\s\S]*\}/)?.[0]].filter(Boolean);
  for (const c of candidates) {
    try {
      const obj = JSON.parse(c);
      const str = (v) => (typeof v === 'string' ? v.trim() : '');
      const name = str(obj.framework_name);
      const takeaway = str(obj.takeaway);
      if (!name || !takeaway) continue;
      return {
        name,
        takeaway,
        situation: str(obj.situation),
        questions: Array.isArray(obj.client_questions)
          ? obj.client_questions.map(str).filter(Boolean).slice(0, 6)
          : [],
      };
    } catch {}
  }
  return null; // no usable framework → stream stays empty rather than storing junk
}

const fw = parseFramework($json.message?.content);
const framework = fw
  ? [{ content: `Framework: ${fw.name}\n${fw.takeaway}`, framework_name: fw.name }]
  : [];

// Contextual enrichment: a session-level header prepended to the text that is EMBEDDED
// (never to the stored content), so short user questions land near the right session.
const retrieval_context = fw && (fw.situation || fw.questions.length)
  ? { situation: fw.situation, client_questions: fw.questions }
  : null;
const embedHeader = retrieval_context
  ? [
      retrieval_context.situation && `Situation: ${retrieval_context.situation}`,
      retrieval_context.client_questions.length && `Questions this addresses: ${retrieval_context.client_questions.join(' ')}`,
    ].filter(Boolean).join('\n') + '\n\n'
  : '';

// ---------- Stream 2: voice_sample ----------
// The coach is the internal team member; client turns are dropped entirely.
const coachNames = new Set(
  session.participants.filter((p) => p.is_team_member).map((p) => p.name)
);
const coachTurns = session.transcript.filter((t) => coachNames.has(t.speaker));

// Sentence units keep the coach's phrasing intact: chunks never cut mid-sentence.
const splitSentences = (text) =>
  (text.match(/[^.!?]+[.!?]+["')\]]*|[^.!?]+$/g) ?? [text]).map((s) => s.trim()).filter(Boolean);

const units = coachTurns.flatMap((turn) =>
  splitSentences(turn.text).map((sentence, i) => ({ sentence, timestamp: turn.timestamp, turnStart: i === 0 }))
);

// A new turn starts on a new line so the original turn rhythm stays visible.
const render = (us) =>
  us.map((u, i) => (i === 0 ? '' : u.turnStart ? '\n' : ' ') + u.sentence).join('');

// Greedy packing: close a chunk once the next sentence would push it past MAX_CHARS.
const groups = [];
let current = [];
for (const unit of units) {
  if (current.length && render([...current, unit]).length > MAX_CHARS && render(current).length >= MIN_CHARS) {
    groups.push(current);
    current = [];
  }
  current.push(unit);
}
if (current.length) groups.push(current);

// A short tail is merged into, or rebalanced with, the previous chunk.
if (groups.length > 1 && render(groups.at(-1)).length < MIN_CHARS) {
  const merged = [...groups.at(-2), ...groups.at(-1)];
  groups.splice(-2, 2);
  if (render(merged).length <= MAX_CHARS) {
    groups.push(merged);
  } else {
    // Split at the sentence boundary closest to the character midpoint
    const half = render(merged).length / 2;
    let cut = 1;
    while (cut < merged.length - 1 && render(merged.slice(0, cut + 1)).length <= half) cut++;
    groups.push(merged.slice(0, cut), merged.slice(cut));
  }
}

const voice_sample = groups.map((g) => ({
  content: render(g),
  turn_timestamps: [...new Set(g.map((u) => u.timestamp))],
}));

// ---------- Output: one item per session, with both streams ----------
const base = {
  title: src.title,
  session_created_at: src.created_at,
  coach: [...coachNames].join(', '),
  clients: session.participants.filter((p) => !p.is_team_member).map((p) => p.name),
  meeting_type: src.meeting_type,
  confidence_score: src.confidence_score,
  source: 'mock_transcripts.json',
  retrieval_context,
};

const chunks = [
  ...framework.map((c, i) => ({
    stream_type: 'framework', chunk_index: i, content: c.content,
    metadata: { ...base, framework_name: c.framework_name, char_count: c.content.length },
  })),
  ...voice_sample.map((c, i) => ({
    stream_type: 'voice_sample', chunk_index: i, content: c.content,
    metadata: { ...base, turn_timestamps: c.turn_timestamps, char_count: c.content.length },
  })),
];

return {
  json: {
    session_id: src.session_id,
    framework: framework.map((c) => c.content),
    voice_sample: voice_sample.map((c) => c.content),
    framework_parse_status: fw ? 'ok' : 'invalid_json',
    chunks,
    embed_request: { model: 'bge-m3', input: chunks.map((c) => embedHeader + c.content) },
  },
};

// Attach Embeddings — "Run Once for Each Item"
// Pairs each chunk with its bge-m3 vector and validates shape before anything touches the DB.
const DIMS = 1024;

const parsed = $('Dual-Stream Parser').item.json;
const vectors = $json.embeddings ?? [];

if (vectors.length !== parsed.chunks.length) {
  throw new Error(`${parsed.session_id}: expected ${parsed.chunks.length} embeddings, got ${vectors.length}`);
}

const rows = parsed.chunks.map((chunk, i) => {
  const v = vectors[i];
  if (!Array.isArray(v) || v.length !== DIMS || !v.every(Number.isFinite)) {
    throw new Error(`${parsed.session_id} ${chunk.stream_type}#${chunk.chunk_index}: invalid ${DIMS}-dim vector`);
  }
  return {
    session_id: parsed.session_id,
    stream_type: chunk.stream_type,
    chunk_index: chunk.chunk_index,
    content: chunk.content,
    metadata: { ...chunk.metadata, embedding_model: 'bge-m3' },
    embedding: `[${v.join(',')}]`, // pgvector text literal, cast to vector in SQL
  };
});

return { json: { session_id: parsed.session_id, row_count: rows.length, rows } };
